import { test, expect } from '@playwright/test';

test.describe('Live Data Last Updated Timestamp', () => {
  let testUrl: string;

  test.beforeEach(async ({ page }) => {
    testUrl = process.env.TEST_URL || 'http://localhost:3000';
    await page.goto(testUrl);
  });

  test('should display last updated timestamp on page load', async ({ page }) => {
    const timestampElement = page.getByText(/last updated/i);
    await expect(timestampElement).toBeVisible();

    const timestampText = await timestampElement.textContent();
    expect(timestampText).toBeTruthy();
    expect(timestampText).toMatch(/\d{1,2}:\d{2}:\d{2}|last updated/i);
  });

  test('should update timestamp when live data refreshes', async ({ page }) => {
    const timestampElement = page.getByText(/last updated/i);
    const initialTimestamp = await timestampElement.textContent();

    await page.waitForTimeout(2000);

    const refreshButton = page.getByRole('button', { name: /refresh|update/i });
    if (await refreshButton.isVisible()) {
      await refreshButton.click();
      await page.waitForTimeout(1000);
    }

    const updatedTimestamp = await timestampElement.textContent();
    expect(updatedTimestamp).toBeTruthy();
  });

  test('should display timestamp in valid datetime format', async ({ page }) => {
    const timestampElement = page.getByText(/last updated/i);
    const timestampText = await timestampElement.textContent();

    const datetimeRegex = /(\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2}).*(\d{1,2}:\d{2}:\d{2})/;
    expect(timestampText).toMatch(datetimeRegex);
  });

  test('should show timestamp in accessible format', async ({ page }) => {
    const timestampContainer = page.getByRole('region', { name: /live data|timestamp/i });
    const timestampElement = page.getByText(/last updated/i);

    await expect(timestampElement).toBeVisible();
    const ariaLabel = await timestampElement.getAttribute('aria-label');

    if (ariaLabel) {
      expect(ariaLabel.toLowerCase()).toContain('updated');
    }
  });
});
